// Package ui embeds the compiled web interface (see web/) so that the theo
// binary serves it without any file next to it. The files in dist/ are
// generated by `npm run build` in web/ and are committed on purpose: `go
// build` and `go install` must work without Node.
package ui

import (
	"embed"
	"io/fs"
)

//go:embed all:dist
var dist embed.FS

// Assets returns the compiled interface, rooted at its index.html.
func Assets() fs.FS {
	sub, err := fs.Sub(dist, "dist")
	if err != nil {
		panic(err) // dist is embedded: it always exists
	}
	return sub
}
